"use client";

import React, { useState } from 'react';
import { questData } from '@/lib/QuestData';
import QuestCard from '@/components/QuestCard';
import { Filter, Trophy } from 'lucide-react';
import {Navigation} from "@/components/Navigation";

const Quests: React.FC = () => {
  const [selectedType, setSelectedType] = useState<string>('All');
  const [selectedDifficulty, setSelectedDifficulty] = useState<string>('All');

  const questTypes = ['All', 'Workshop', 'Submission', 'Challenge', 'Social', 'Bonus'];
  const difficulties = ['All', 'Easy', 'Medium', 'Hard'];

  const filteredQuests = questData.filter(quest => {
    const typeMatch = selectedType === 'All' || quest.type === selectedType;
    const difficultyMatch = selectedDifficulty === 'All' || quest.difficulty === selectedDifficulty;
    return typeMatch && difficultyMatch;
  });

  return (
      <>
        <Navigation/>
        <br/><br/>
        <div className="min-h-screen bg-darker">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
            {/* Header */}
            <div className="text-center mb-12">
              <h1 className="text-5xl font-bold text-light mb-4">
                <span className="text-neon-purple animate-glow">QUEST</span> LOG
              </h1>
              <p className="text-xl text-gray-custom mb-8">
                Complete challenges, earn Checkpoint Points, and level up your hackathon game
              </p>
            </div>

            {/* Filters */}
            <div className="flex flex-col md:flex-row items-center justify-between mb-8 space-y-4 md:space-y-0">
              <div className="flex items-center space-x-4">
                <Filter className="w-5 h-5 text-gray-custom"/>
                <span className="text-gray-custom font-medium">Filter by:</span>
              </div>

              <div className="flex flex-wrap gap-4">
                <div className="flex items-center space-x-2">
                  <span className="text-sm text-gray-custom">Type:</span>
                  <select
                      value={selectedType}
                      onChange={(e) => setSelectedType(e.target.value)}
                      className="bg-dark-bg border border-gray-700 rounded-lg px-3 py-2 text-light text-sm focus:border-accent-purple focus:outline-none"
                  >
                    {questTypes.map(type => (
                        <option key={type} value={type}>{type}</option>
                    ))}
                  </select>
                </div>

                <div className="flex items-center space-x-2">
                  <span className="text-sm text-gray-custom">Difficulty:</span>
                  <select
                      value={selectedDifficulty}
                      onChange={(e) => setSelectedDifficulty(e.target.value)}
                      className="bg-dark-bg border border-gray-700 rounded-lg px-3 py-2 text-light text-sm focus:border-accent-purple focus:outline-none"
                  >
                    {difficulties.map(difficulty => (
                        <option key={difficulty} value={difficulty}>{difficulty}</option>
                    ))}
                  </select>
                </div>
              </div>
            </div>

            {/* Quest Grid */}
            <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredQuests.map(quest => (
                  <QuestCard key={quest.id} quest={quest}/>
              ))}
            </div>

            {filteredQuests.length === 0 && (
                <div className="text-center py-12">
                  <Trophy className="w-16 h-16 text-gray-600 mx-auto mb-4"/>
                  <h3 className="text-xl font-bold text-gray-custom mb-2">No quests found</h3>
                  <p className="text-gray-custom">Try adjusting your filters to see more quests.</p>
                </div>
            )}
          </div>
        </div>
      </>
  );
};

export default Quests;

"use client";

import React, { useState } from 'react';
import { questData } from '@/lib/QuestData';
import QuestCard from '@/components/QuestCard';
import { Filter, Trophy } from 'lucide-react';
import {Navigation} from "@/components/Navigation";

const Quests: React.FC = () => {
  const [selectedType, setSelectedType] = useState<string>('All');
  const [selectedDifficulty, setSelectedDifficulty] = useState<string>('All');

  const questTypes = ['All', 'Workshop', 'Submission', 'Challenge', 'Social', 'Bonus'];
  const difficulties = ['All', 'Easy', 'Medium', 'Hard'];

  const filteredQuests = questData.filter(quest => {
    const typeMatch = selectedType === 'All' || quest.type === selectedType;
    const difficultyMatch = selectedDifficulty === 'All' || quest.difficulty === selectedDifficulty;
    return typeMatch && difficultyMatch;
  });

  return (
      <>
        <Navigation/>
        <div className="min-h-screen" style={{background: 'linear-gradient(135deg, var(--dark-background), var(--darker-background))'}}>
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12 pt-24">
            {/* Header */}
            <div className="text-center mb-12">
              <h1 className="text-5xl font-bold mb-4" style={{
                background: 'linear-gradient(45deg, var(--accent-purple), var(--accent-pink))',
                WebkitBackgroundClip: 'text',
                WebkitTextFillColor: 'transparent',
                backgroundClip: 'text'
              }}>
                QUEST LOG
              </h1>
              <p className="text-xl mb-8" style={{color: 'var(--text-gray)'}}>
                Complete challenges, earn Checkpoint Points, and level up your hackathon game
              </p>
            </div>

            {/* Filters */}
            <div className="flex flex-col md:flex-row items-center justify-between mb-8 space-y-4 md:space-y-0">
              <div className="flex items-center space-x-4">
                <Filter className="w-5 h-5" style={{color: 'var(--text-gray)'}}/>
                <span className="font-medium" style={{color: 'var(--text-gray)'}}>Filter by:</span>
              </div>

              <div className="flex flex-wrap gap-4">
                <div className="flex items-center space-x-2">
                  <span className="text-sm" style={{color: 'var(--text-gray)'}}>Type:</span>
                  <select
                      value={selectedType}
                      onChange={(e) => setSelectedType(e.target.value)}
                      className="rounded-lg px-3 py-2 text-sm focus:outline-none"
                      style={{
                        background: 'rgba(255, 255, 255, 0.05)',
                        border: '1px solid rgba(255, 255, 255, 0.1)',
                        color: 'var(--text-light)'
                      }}
                  >
                    {questTypes.map(type => (
                        <option key={type} value={type}>{type}</option>
                    ))}
                  </select>
                </div>

                <div className="flex items-center space-x-2">
                  <span className="text-sm" style={{color: 'var(--text-gray)'}}>Difficulty:</span>
                  <select
                      value={selectedDifficulty}
                      onChange={(e) => setSelectedDifficulty(e.target.value)}
                      className="rounded-lg px-3 py-2 text-sm focus:outline-none"
                      style={{
                        background: 'rgba(255, 255, 255, 0.05)',
                        border: '1px solid rgba(255, 255, 255, 0.1)',
                        color: 'var(--text-light)'
                      }}
                  >
                    {difficulties.map(difficulty => (
                        <option key={difficulty} value={difficulty}>{difficulty}</option>
                    ))}
                  </select>
                </div>
              </div>
            </div>

            {/* Quest Grid */}
            <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredQuests.map(quest => (
                  <QuestCard key={quest.id} quest={quest}/>
              ))}
            </div>

            {filteredQuests.length === 0 && (
                <div className="text-center py-12">
                  <Trophy className="w-16 h-16 mx-auto mb-4" style={{color: 'var(--text-gray)'}}/>
                  <h3 className="text-xl font-bold mb-2" style={{color: 'var(--text-gray)'}}>No quests found</h3>
                  <p style={{color: 'var(--text-gray)'}}>Try adjusting your filters to see more quests.</p>
                </div>
            )}
          </div>
        </div>
      </>
  );
};

export default Quests;

'use client';

import Image from 'next/image';
import {FaCoins} from 'react-icons/fa';
import {storeItems} from "@/lib/ShopData";


export default function ShopPage() {
    return (
        <section className="content-section">
            <h2 className="text-4xl font-bold mb-8 bg-gradient-to-r from-blue-400 to-purple-500 bg-clip-text text-transparent">
                Store
            </h2>
            <div className="grid md:grid-cols-2 gap-8">
                {storeItems.map((item, idx) => (
                    <div
                        key={idx}
                        className="bg-gradient-to-br from-slate-900 via-blue-900 to-slate-900 rounded-xl p-6 shadow-lg border border-white/10 flex items-center gap-6 hover:scale-105 transition-transform"
                    >
                        <div className="shrink-0">
                            <Image
                                src={item.img}
                                alt={item.name}
                                width={64}
                                height={64}
                                className="rounded-lg shadow-md"
                            />
                        </div>
                        <div className="flex-1">
                            <h3 className="text-2xl font-semibold mb-1 text-accent-blue flex items-center gap-2">
                                {item.icon} {item.name}
                            </h3>
                            <p className="text-text-gray mb-2">{item.desc}</p>
                            <div className="flex gap-4 items-center mt-2">
                                <span
                                    className="inline-flex items-center gap-1 px-3 py-1 rounded bg-gradient-to-r from-accent-blue to-accent-purple text-white font-bold text-sm">
                                    <FaCoins className="text-yellow-400"/> {item.price} Starting
                                    Bid
                                </span>
                                <span
                                    className="inline-flex items-center gap-1 px-3 py-1 rounded bg-gradient-to-r from-accent-green to-accent-blue text-white font-bold text-sm">
                                    Stock: {item.stock}
                                </span>
                            </div>
                        </div>
                    </div>
                ))}
            </div>
        </section>
    );
}

'use client';

import Image from 'next/image';
import { FaCoins } from 'react-icons/fa';
import { storeItems } from "@/lib/ShopData";
import { useState, useEffect } from 'react';
import { motion } from 'framer-motion';

export default function ShopPage() {
    const [hoveredItem, setHoveredItem] = useState<number | null>(null);
    const [isPageLoaded, setIsPageLoaded] = useState(false);

    useEffect(() => {
        setIsPageLoaded(true);
    }, []);

    return (
        <section className="content-section relative min-h-screen py-10 px-4">
            {/* Cyberpunk/RPG style header */}
            <div className="relative z-10 mb-12">
                <h2 className="glitch-text text-5xl font-black tracking-wider uppercase mb-2">
                    MARKETPLACE
                    <span className="glitch-span" aria-hidden="true">MARKETPLACE</span>
                </h2>
                <p className="text-accent-blue text-lg italic tracking-wide max-w-lg">
                    Enhance your experience with rare items and power-ups
                </p>
            </div>

            {/* Animated coin counter */}
            <motion.div 
                className="fixed top-5 right-5 flex items-center bg-black/50 backdrop-blur-md px-4 py-2 rounded-full border-2 border-yellow-500 z-50"
                initial={{ y: -50, opacity: 0 }}
                animate={{ y: 0, opacity: 1 }}
                transition={{ delay: 0.5, type: "spring" }}
            >
                <FaCoins className="text-yellow-400 text-xl mr-2" />
                <span className="text-yellow-400 font-mono font-bold">1,250</span>
            </motion.div>

            {/* Hexagon grid container */}
            <div className="hex-grid">
                {storeItems.map((item, idx) => (
                    <motion.div
                        key={idx}
                        className={`hex-item ${hoveredItem === idx ? 'hex-item-active' : ''}`}
                        onMouseEnter={() => setHoveredItem(idx)}
                        onMouseLeave={() => setHoveredItem(null)}
                        initial={{ opacity: 0, y: 20 }}
                        animate={{ 
                            opacity: isPageLoaded ? 1 : 0, 
                            y: isPageLoaded ? 0 : 20 
                        }}
                        transition={{ delay: idx * 0.1 }}
                    >
                        <div className="hex-content">
                            <div className="hex-img-wrapper">
                                <Image
                                    src={item.img}
                                    alt={item.name}
                                    width={80}
                                    height={80}
                                    className="hex-img"
                                />
                                {item.icon && <div className="hex-icon">{item.icon}</div>}
                            </div>

                            <h3 className="hex-title">{item.name}</h3>

                            <div className="hex-details">
                                <p className="hex-desc">{item.desc}</p>

                                <div className="hex-price-tag">
                                    <FaCoins className="text-yellow-400" />
                                    <span>{item.price}</span>
                                </div>

                                <div className="hex-stock">
                                    <span className={`stock-indicator ${item.stock > 5 ? 'high' : item.stock > 0 ? 'medium' : 'low'}`}></span>
                                    <span>{item.stock > 0 ? `${item.stock} available` : 'Out of stock'}</span>
                                </div>
                            </div>

                            <button className="hex-button">
                                {item.stock > 0 ? 'Purchase' : 'Notify Me'}
                            </button>
                        </div>
                    </motion.div>
                ))}
            </div>

            {/* Background elements */}
            <div className="shop-bg-elements"></div>

            {/* Add CSS for our custom shop styling */}
            <style jsx global>{`
                .content-section {
                    background: radial-gradient(circle at center, #111827, #0a101f);
                    overflow: hidden;
                }

                /* Glitch text effect */
                .glitch-text {
                    position: relative;
                    color: #f5f5f5;
                    text-shadow: 0 0 10px rgba(66, 220, 219, 0.8);
                }

                .glitch-span {
                    position: absolute;
                    top: 0;
                    left: 0;
                    color: transparent;
                    text-shadow: 2px 0 #ff00ea, -2px 0 #00f0ff;
                    clip: rect(44px, 450px, 56px, 0);
                    animation: glitch 5s infinite linear alternate-reverse;
                    opacity: 0.5;
                }

                @keyframes glitch {
                    0% { clip: rect(44px, 450px, 56px, 0); }
                    5% { clip: rect(4px, 450px, 36px, 0); }
                    10% { clip: rect(24px, 450px, 76px, 0); }
                    15% { clip: rect(64px, 450px, 96px, 0); }
                    20% { clip: rect(14px, 450px, 46px, 0); }
                    25% { clip: rect(34px, 450px, 86px, 0); }
                    100% { clip: rect(44px, 450px, 56px, 0); }
                }

                /* Hex grid layout */
                .hex-grid {
                    display: grid;
                    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
                    gap: 30px;
                    max-width: 1200px;
                    margin: 0 auto;
                    padding: 20px;
                }

                /* Hex item styling */
                .hex-item {
                    position: relative;
                    height: 320px;
                    background: linear-gradient(135deg, rgba(30,41,59,0.8) 0%, rgba(15,23,42,0.9) 100%);
                    border-radius: 12px;
                    transition: all 0.3s cubic-bezier(0.175, 0.885, 0.32, 1.275);
                    box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.2), 0 0 0 1px rgba(255, 255, 255, 0.05);
                    overflow: hidden;
                    backdrop-filter: blur(5px);
                }

                .hex-item::before {
                    content: '';
                    position: absolute;
                    top: -2px;
                    left: -2px;
                    right: -2px;
                    bottom: -2px;
                    background: linear-gradient(45deg, #00f2ff, #4facfe, #0066ff, #bd00ff);
                    z-index: -1;
                    border-radius: 14px;
                    opacity: 0;
                    transition: opacity 0.3s;
                }

                .hex-item-active {
                    transform: translateY(-8px) scale(1.02);
                }

                .hex-item-active::before {
                    opacity: 1;
                    animation: rotate 3s linear infinite;
                }

                @keyframes rotate {
                    0% { background-position: 0% 50%; }
                    50% { background-position: 100% 50%; }
                    100% { background-position: 0% 50%; }
                }

                .hex-content {
                    display: flex;
                    flex-direction: column;
                    height: 100%;
                    padding: 20px;
                    position: relative;
                    z-index: 10;
                }

                /* Image styling */
                .hex-img-wrapper {
                    position: relative;
                    margin: 0 auto 15px;
                }

                .hex-img {
                    border-radius: 8px;
                    object-fit: cover;
                    transition: transform 0.5s;
                    box-shadow: 0 0 15px rgba(0, 247, 255, 0.3);
                }

                .hex-item-active .hex-img {
                    transform: scale(1.1) rotate(-3deg);
                }

                .hex-icon {
                    position: absolute;
                    bottom: -10px;
                    right: -10px;
                    background: rgba(0, 0, 0, 0.7);
                    border-radius: 50%;
                    padding: 5px;
                    border: 2px solid #4facfe;
                    font-size: 1.2rem;
                }

                /* Title styling */
                .hex-title {
                    font-size: 1.5rem;
                    font-weight: 800;
                    text-align: center;
                    margin-bottom: 10px;
                    color: white;
                    text-shadow: 0 0 10px rgba(66, 220, 219, 0.8);
                    letter-spacing: 0.5px;
                }

                /* Details styling */
                .hex-details {
                    flex: 1;
                    display: flex;
                    flex-direction: column;
                    margin: 10px 0;
                }

                .hex-desc {
                    font-size: 0.9rem;
                    color: #d1d5db;
                    text-align: center;
                    margin-bottom: 15px;
                }

                /* Price tag styling */
                .hex-price-tag {
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    gap: 5px;
                    background: linear-gradient(90deg, #ffd700, #ffa500);
                    padding: 5px 15px;
                    border-radius: 20px;
                    font-weight: bold;
                    color: black;
                    margin: 5px auto;
                    width: fit-content;
                }

                /* Stock indicator */
                .hex-stock {
                    display: flex;
                    align-items: center;
                    justify-content: center;
                    gap: 6px;
                    margin-top: 10px;
                    font-size: 0.85rem;
                    color: #cbd5e1;
                }

                .stock-indicator {
                    width: 8px;
                    height: 8px;
                    border-radius: 50%;
                }

                .stock-indicator.high { background-color: #10b981; }
                .stock-indicator.medium { background-color: #f59e0b; }
                .stock-indicator.low { background-color: #ef4444; }

                /* Button styling */
                .hex-button {
                    background: linear-gradient(45deg, #4facfe 0%, #00f2fe 100%);
                    border: none;
                    border-radius: 5px;
                    padding: 8px 0;
                    font-weight: bold;
                    color: white;
                    cursor: pointer;
                    transition: all 0.3s;
                    text-transform: uppercase;
                    letter-spacing: 1px;
                    position: relative;
                    overflow: hidden;
                    text-shadow: 0 0 2px rgba(0, 0, 0, 0.5);
                }

                .hex-button::after {
                    content: '';
                    position: absolute;
                    top: -50%;
                    left: -60%;
                    width: 20px;
                    height: 200%;
                    background: rgba(255, 255, 255, 0.3);
                    transform: rotate(25deg);
                    transition: transform 0.6s;
                }

                .hex-item-active .hex-button::after {
                    transform: translateX(500%) rotate(25deg);
                }

                .hex-button:hover {
                    transform: translateY(-2px);
                    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.3);
                }

                /* Background elements */
                .shop-bg-elements {
                    position: fixed;
                    top: 0;
                    left: 0;
                    width: 100%;
                    height: 100%;
                    pointer-events: none;
                    z-index: 0;
                    overflow: hidden;
                }

                .shop-bg-elements::before,
                .shop-bg-elements::after {
                    content: '';
                    position: absolute;
                    width: 300px;
                    height: 300px;
                    border-radius: 50%;
                    background: radial-gradient(circle, rgba(66, 220, 219, 0.2) 0%, rgba(66, 220, 219, 0) 70%);
                    animation: float 20s infinite alternate ease-in-out;
                }

                .shop-bg-elements::before {
                    top: 10%;
                    left: 10%;
                    animation-delay: 0s;
                }

                .shop-bg-elements::after {
                    bottom: 10%;
                    right: 10%;
                    width: 400px;
                    height: 400px;
                    background: radial-gradient(circle, rgba(255, 0, 255, 0.1) 0%, rgba(255, 0, 255, 0) 70%);
                    animation-delay: -10s;
                }

                @keyframes float {
                    0% { transform: translate(0, 0); }
                    50% { transform: translate(-30px, 20px); }
                    100% { transform: translate(30px, -20px); }
                }

                /* Responsive adjustments */
                @media (max-width: 768px) {
                    .hex-grid {
                        grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
                        gap: 20px;
                    }

                    .hex-item {
                        height: 300px;
                    }

                    .glitch-text {
                        font-size: 2.5rem;
                    }
                }
            `}</style>
        </section>
    );
}

"use client";

import React, { useState } from 'react';
import { storeItems } from '@/lib/StoreData';
import StoreItemComponent from '@/components/StoreItem';
import { ShoppingBag, Package, Filter, Trophy } from 'lucide-react';
import {Navigation} from "@/components/Navigation";

const Store: React.FC = () => {
  const [selectedCategory, setSelectedCategory] = useState<string>('All');
  const [selectedRarity, setSelectedRarity] = useState<string>('All');

  const categories = ['All', 'Apparel', 'Tech', 'Collectible', 'Experience'];
  const rarities = ['All', 'Common', 'Rare', 'Epic', 'Legendary'];

  const filteredItems = storeItems.filter(item => {
    const categoryMatch = selectedCategory === 'All' || item.category === selectedCategory;
    const rarityMatch = selectedRarity === 'All' || item.rarity === selectedRarity;
    return categoryMatch && rarityMatch;
  });

  return (
      <>
        <Navigation/>
        <br/><br/>
        <div className="min-h-screen bg-darker">
          <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
            {/* Header */}
            <div className="text-center mb-12">
              <h1 className="text-5xl font-bold text-light mb-4">
                <span className="text-neon-green animate-glow">CHECKPOINT</span> STORE
              </h1>
              <p className="text-xl text-gray-custom mb-8">
                Bid on exclusive items using your hard-earned Checkpoint Points
              </p>


              {/* Auction Info */}
              <div className="mt-16 bg-dark-bg border border-accent-purple/30 rounded-xl p-8">
                <h2 className="text-2xl font-bold text-light mb-4 text-center">How Bidding Works</h2>
                <div className="grid md:grid-cols-3 gap-6 text-center">
                  <div>
                    <Package className="w-8 h-8 text-neon-purple mx-auto mb-3"/>
                    <h3 className="font-bold text-light mb-2">Choose Your Item</h3>
                    <p className="text-sm text-gray-custom">Browse through our exclusive collection of hackathon
                      rewards</p>
                  </div>
                  <div>
                    <ShoppingBag className="w-8 h-8 text-neon-green mx-auto mb-3"/>
                    <h3 className="font-bold text-light mb-2">Place Your Bid</h3>
                    <p className="text-sm text-gray-custom">Use your earned CP to bid on items you want once the auction
                      begins</p>
                  </div>
                  <div>
                    <Trophy className="w-8 h-8 text-neon-blue mx-auto mb-3"/>
                    <h3 className="font-bold text-light mb-2">Win & Collect</h3>
                    <p className="text-sm text-gray-custom">Highest bidder wins when the auction ends - as a tip have
                      1.5x the start bid amount.</p>
                  </div>
                </div>
              </div>
            </div>

            {/* Filters */}
            <div className="flex flex-col md:flex-row items-center justify-between mb-8 space-y-4 md:space-y-0">
              <div className="flex items-center space-x-4">
                <Filter className="w-5 h-5 text-gray-custom"/>
                <span className="text-gray-custom font-medium">Filter by:</span>
              </div>

              <div className="flex flex-wrap gap-4">
                <div className="flex items-center space-x-2">
                  <span className="text-sm text-gray-custom">Category:</span>
                  <select
                      value={selectedCategory}
                      onChange={(e) => setSelectedCategory(e.target.value)}
                      className="bg-dark-bg border border-gray-700 rounded-lg px-3 py-2 text-light text-sm focus:border-accent-green focus:outline-none"
                  >
                    {categories.map(category => (
                        <option key={category} value={category}>{category}</option>
                    ))}
                  </select>
                </div>

                <div className="flex items-center space-x-2">
                  <span className="text-sm text-gray-custom">Rarity:</span>
                  <select
                      value={selectedRarity}
                      onChange={(e) => setSelectedRarity(e.target.value)}
                      className="bg-dark-bg border border-gray-700 rounded-lg px-3 py-2 text-light text-sm focus:border-accent-green focus:outline-none"
                  >
                    {rarities.map(rarity => (
                        <option key={rarity} value={rarity}>{rarity}</option>
                    ))}
                  </select>
                </div>
              </div>
            </div>

            {/* Store Grid */}
            <div className="grid md:grid-cols-2 lg:grid-cols-3 gap-6">
              {filteredItems.map(item => (
                  <StoreItemComponent key={item.id} item={item}/>
              ))}
            </div>

            {filteredItems.length === 0 && (
                <div className="text-center py-12">
                  <ShoppingBag className="w-16 h-16 text-gray-600 mx-auto mb-4"/>
                  <h3 className="text-xl font-bold text-gray-custom mb-2">No items found</h3>
                  <p className="text-gray-custom">Try adjusting your filters to see more items.</p>
                </div>
            )}
          </div>
        </div>
      </>
  );
};

export default Store;

"use client";

